package main

import (
	"encoding/json"
	"os"
	"regexp"
	"strings"
	"testing"

	"gopkg.in/yaml.v3"
)

// S6: the Postman collection for the ERP partner is generated by
// docs/erp-api/oas2postman.py from the embedded contract. These tests pin the
// committed files to the contract: the shape the partner imports, that every
// contract operation is a request, and that no internal detail leaked in.

const (
	postmanCollectionPath   = "../../docs/erp-api/dawa24-erp.postman_collection.json"
	postmanEnvironmentPath  = "../../docs/erp-api/dawa24-erp.postman_environment.json"
	postmanContractPath     = "../../internal/modules/erp/http/spec/openapi.yaml"
	postmanCollectionSchema = "https://schema.getpostman.com/json/collection/v2.1.0/collection.json"
)

// postmanNode is one folder or request in the collection tree.
type postmanNode struct {
	Name    string        `json:"name"`
	Item    []postmanNode `json:"item"`
	Request *struct {
		Method      string          `json:"method"`
		URL         json.RawMessage `json:"url"`
		Description string          `json:"description"`
		Auth        *postmanAuth    `json:"auth"`
	} `json:"request"`
	Event []struct {
		Listen string `json:"listen"`
		Script struct {
			Exec []string `json:"exec"`
		} `json:"script"`
	} `json:"event"`
}

// postmanAuth is a Postman auth block; the bearer token sits in the first entry.
type postmanAuth struct {
	Type   string `json:"type"`
	Bearer []struct {
		Key   string `json:"key"`
		Value string `json:"value"`
	} `json:"bearer"`
}

type postmanCollection struct {
	Info struct {
		Schema string `json:"schema"`
	} `json:"info"`
	Auth *postmanAuth  `json:"auth"`
	Item []postmanNode `json:"item"`
}

func readPostmanCollection(t *testing.T) (postmanCollection, []byte) {
	t.Helper()
	raw, err := os.ReadFile(postmanCollectionPath)
	if err != nil {
		t.Fatalf("read collection: %v (run docs/erp-api/oas2postman.py)", err)
	}
	var c postmanCollection
	if err := json.Unmarshal(raw, &c); err != nil {
		t.Fatalf("collection is not JSON: %v", err)
	}
	return c, raw
}

// requestNodes returns every request with its folder name.
func requestNodes(items []postmanNode, folder string) []struct {
	Folder string
	Node   postmanNode
} {
	var out []struct {
		Folder string
		Node   postmanNode
	}
	for _, it := range items {
		if it.Request == nil {
			out = append(out, requestNodes(it.Item, it.Name)...)
			continue
		}
		out = append(out, struct {
			Folder string
			Node   postmanNode
		}{folder, it})
	}
	return out
}

// requestPath is the contract path a request calls, with {{var}} written as {var}.
func requestPath(raw json.RawMessage) string {
	var asString string
	if json.Unmarshal(raw, &asString) == nil {
		asString = strings.TrimPrefix(asString, "{{baseUrl}}")
	} else {
		var obj struct {
			Raw string `json:"raw"`
		}
		_ = json.Unmarshal(raw, &obj)
		asString = strings.TrimPrefix(obj.Raw, "{{baseUrl}}")
	}
	if i := strings.Index(asString, "?"); i >= 0 {
		asString = asString[:i]
	}
	asString = strings.TrimPrefix(asString, "/erp/v1")
	// Postman writes path parameters as :name and variables as {{name}}.
	asString = regexp.MustCompile(`:([A-Za-z][A-Za-z0-9_]*)`).ReplaceAllString(asString, "{$1}")
	return regexp.MustCompile(`\{\{([A-Za-z0-9_$]+)\}\}`).ReplaceAllString(asString, "{$1}")
}

// bearerKeyOK reports whether an auth block sends the key as a bearer token.
func bearerKeyOK(a *postmanAuth) bool {
	if a == nil || a.Type != "bearer" {
		return false
	}
	for _, b := range a.Bearer {
		if b.Key == "token" && b.Value == "{{apiKey}}" {
			return true
		}
	}
	return false
}

func TestPostmanCollectionShape(t *testing.T) {
	c, raw := readPostmanCollection(t)
	if c.Info.Schema != postmanCollectionSchema {
		t.Fatalf("schema = %q, want Collection v2.1", c.Info.Schema)
	}
	// Every request inherits the collection's bearer key; a request may override it.
	if !bearerKeyOK(c.Auth) {
		t.Fatalf("collection auth = %+v, want bearer {{apiKey}}", c.Auth)
	}

	wantFolders := []string{"01 ", "02 ", "03 ", "04 "}
	if len(c.Item) != len(wantFolders) {
		t.Fatalf("%d folders, want %d numbered folders", len(c.Item), len(wantFolders))
	}
	for i, f := range c.Item {
		if !strings.HasPrefix(f.Name, wantFolders[i]) || f.Request != nil {
			t.Fatalf("folder %d = %q, want a folder starting %q", i, f.Name, wantFolders[i])
		}
	}

	for _, r := range requestNodes(c.Item, "") {
		if !strings.Contains(r.Node.Name, ". ") {
			t.Errorf("request %q is not numbered", r.Node.Name)
		}
		if r.Node.Request.Auth != nil && !bearerKeyOK(r.Node.Request.Auth) {
			t.Errorf("request %q overrides the bearer key", r.Node.Name)
		}
		hasTest := false
		for _, ev := range r.Node.Event {
			if ev.Listen == "test" && strings.Contains(strings.Join(ev.Script.Exec, "\n"), "pm.test") {
				hasTest = true
			}
		}
		if !hasTest {
			t.Errorf("request %q has no pm.test script", r.Node.Name)
		}
	}

	// S7 mounted find offers and create purchase order, so no request in the
	// purchase folder may still carry the "Coming soon" mark.
	comingSoon := 0
	for _, it := range c.Item[3].Item {
		if it.Request != nil && strings.Contains(it.Request.Description, "Coming soon") {
			comingSoon++
		}
	}
	if comingSoon != 0 {
		t.Errorf("purchase folder marks %d requests coming soon, want 0 now that S7 mounts them", comingSoon)
	}

	text := string(raw)
	for _, leak := range []string{"internal/", "specs/", "contracts/", "docs/", ".go", "TODO", "unverified", "fields.go"} {
		if strings.Contains(text, leak) {
			t.Errorf("collection contains internal text %q", leak)
		}
	}

	envRaw, err := os.ReadFile(postmanEnvironmentPath)
	if err != nil {
		t.Fatalf("read environment: %v", err)
	}
	var env struct {
		Values []struct {
			Key   string `json:"key"`
			Value string `json:"value"`
		} `json:"values"`
	}
	if err := json.Unmarshal(envRaw, &env); err != nil {
		t.Fatalf("environment is not JSON: %v", err)
	}
	keys := map[string]bool{}
	for _, v := range env.Values {
		keys[v.Key] = true
		if v.Key == "apiKey" && v.Value != "" && strings.HasPrefix(v.Value, "d24_") {
			t.Errorf("environment holds a real-looking key; it must be a placeholder")
		}
	}
	if !keys["baseUrl"] || !keys["apiKey"] {
		t.Errorf("environment keys = %v, want baseUrl and apiKey", keys)
	}
}

// TestPostmanCollectionCoversContract checks that every operation in the
// embedded contract is a request in the collection. The documentation endpoint
// GET /openapi.yaml is not a step of the partner's journey and is excluded.
func TestPostmanCollectionCoversContract(t *testing.T) {
	c, _ := readPostmanCollection(t)
	covered := map[string]bool{}
	for _, r := range requestNodes(c.Item, "") {
		covered[r.Node.Request.Method+" "+requestPath(r.Node.Request.URL)] = true
	}

	specRaw, err := os.ReadFile(postmanContractPath)
	if err != nil {
		t.Fatalf("read contract: %v", err)
	}
	var doc struct {
		Paths map[string]map[string]yaml.Node `yaml:"paths"`
	}
	if err := yaml.Unmarshal(specRaw, &doc); err != nil {
		t.Fatalf("contract does not parse: %v", err)
	}
	for path, ops := range doc.Paths {
		if path == "/openapi.yaml" {
			continue
		}
		for method := range ops {
			switch method {
			case "get", "post", "put", "patch", "delete":
			default:
				continue
			}
			key := strings.ToUpper(method) + " " + path
			if !covered[key] {
				t.Errorf("contract operation %s has no request in the collection", key)
			}
		}
	}
}

func mustJSON(v any) []byte {
	b, _ := json.Marshal(v)
	return b
}
